import pandas as pd,numpy as np
from scipy.optimize import least_squares
fs=['train/A_vref_op1.csv','train/A_vref_op3.csv','val/A_val_vref_op2.csv']
D={f:pd.read_csv(f) for f in fs}
dt=1e-3
def sim(p,d):
    tau,G,Kq=p
    V=d.voltage_pu.values; Vs=d.voltage_setpoint_pu.values
    Q0=d.reactive_power_pu.values[0]; V0=V[0]
    x=Q0; out=np.empty(len(d)); out[0]=x
    for k in range(len(d)-1):
        Vi=Vs[k]-Kq*(x-Q0)
        x=x+dt/tau*(Q0+G*(Vi-V[k])-x)
        out[k+1]=x
    return out
def res(p):
    return np.concatenate([sim(p,D[f])[1:]-D[f].reactive_power_pu.values[1:] for f in fs])
r=least_squares(res,[0.01,10,0.04],x_scale=[0.01,10,0.04],bounds=([1e-4,0,0],[1,200,1]))
print(r.x,np.std(r.fun))
for f in fs: print(f,np.std(sim(r.x,D[f])[1:]-D[f].reactive_power_pu.values[1:]))

